-- Two independent platform menus. Existing raw subjects and plan keys stay intact.
CREATE TABLE academic_catalogues (
 scope TEXT PRIMARY KEY CHECK(scope IN ('student','quiz')),
 revision INTEGER NOT NULL DEFAULT 1 CHECK(revision>0),
 content_json TEXT NOT NULL CHECK(json_valid(content_json)),
 updated_at TEXT NOT NULL,
 updated_by TEXT
);
ALTER TABLE students ADD COLUMN syllabus_id TEXT NOT NULL DEFAULT 'spm';
ALTER TABLE students ADD COLUMN grade TEXT;
ALTER TABLE students ADD COLUMN age INTEGER CHECK(age IS NULL OR (age>=0 AND age<=100));
ALTER TABLE plans ADD COLUMN subject_id TEXT;
ALTER TABLE classrooms ADD COLUMN syllabus_id TEXT;
ALTER TABLE classrooms ADD COLUMN subject_id TEXT;
ALTER TABLE classrooms ADD COLUMN grade TEXT;
CREATE INDEX students_academic_catalogue_idx ON students(group_id,syllabus_id,grade);
CREATE INDEX plans_academic_subject_idx ON plans(group_id,subject_id);
CREATE INDEX classrooms_academic_catalogue_idx ON classrooms(group_id,syllabus_id,grade,subject_id);
CREATE TABLE student_grade_promotions (
 group_id TEXT NOT NULL REFERENCES tuition_groups(id),
 student_name TEXT NOT NULL,
 cycle INTEGER NOT NULL CHECK(cycle>0),
 syllabus_id TEXT NOT NULL,
 from_grade TEXT NOT NULL,
 to_grade TEXT NOT NULL,
 confirmed_by TEXT NOT NULL,
 confirmed_at TEXT NOT NULL,
 PRIMARY KEY(group_id,student_name,cycle),
 FOREIGN KEY(group_id,student_name) REFERENCES students(group_id,name) ON DELETE CASCADE
);
